def lower_bound(prices, k, d):
    """admissible lower bound; -1 means infeasible"""
    n, S = len(prices), sum(prices)
    if max(prices) - min(prices) < d:
        return 0
    lo_L = -(-(S - n * (d - 1)) // n)   # window [L, L+d-1] must hold the sum S
    hi_L = S // n
    best = -1
    for L in range(lo_L, hi_L + 1):
        R = L + d - 1
        A = B = 0             # increase-ops / decrease-ops forced by clamping
        base = 0              # sum after clamping every price into [L, R]
        up_free = dn_free = 0  # slack inside already-paid chunks
        up_full = dn_full = 0  # full k-chunks still available (cost 1 each)
        up_rem, dn_rem = [], []  # partial chunks (cost 1 each)

        def add_cap(cap, full, rem):
            if cap > 0:
                rem.append(cap % k) if cap % k else None
                return full + cap // k
            return full

        for a in prices:
            if a < L:
                g = L - a; c = -(-g // k); A += c; base += L
                free = min(c * k - g, R - L); up_free += free
                up_full = add_cap(R - L - free, up_full, up_rem)
            elif a > R:
                l = a - R; c = -(-l // k); B += c; base += R
                free = min(c * k - l, R - L); dn_free += free
                dn_full = add_cap(R - L - free, dn_full, dn_rem)
            else:
                base += a
                up_full = add_cap(R - a, up_full, up_rem)
                dn_full = add_cap(a - L, dn_full, dn_rem)

        delta = S - base
        if delta > 0:
            A += extra(delta - up_free, up_full, up_rem, k)
        elif delta < 0:
            B += extra(-delta - dn_free, dn_full, dn_rem, k)
        ops = max(A, B)
        if best == -1 or ops < best:
            best = ops
    return best


def extra(need, full, rem, k):
    """fewest pieces (full k-chunks, then partial chunks largest first) covering need"""
    if need <= 0:
        return 0
    if need <= full * k:
        return -(-need // k)
    cnt, need = full, need - full * k
    for r in sorted(rem, reverse=True):
        cnt += 1; need -= r
        if need <= 0:
            return cnt
    raise AssertionError("window cannot hold the sum")


def minOperations(prices, k, d):
    """exact answer: IDA* over sorted states, pruned by lower_bound"""
    start = tuple(sorted(prices))
    h0 = lower_bound(start, k, d)
    if h0 <= 0:
        return h0  # 0: already fine, -1: impossible (d == 1 and n does not divide the sum)
    n = len(start)
    hcache = {}

    def h(s):
        if s not in hcache:
            hcache[s] = lower_bound(s, k, d)
        return hcache[s]

    def dfs(s, g, limit, seen):
        hs = h(s)
        if hs == 0:
            return True
        if g + hs > limit:
            return False
        for x in range(n):
            for y in range(n):
                if x == y or (x > 0 and s[x] == s[x - 1]) or (y > 0 and s[y] == s[y - 1]):
                    continue  # equal values are interchangeable
                for p in range(1, k + 1):
                    b = list(s); b[x] += p; b[y] -= p
                    t = tuple(sorted(b))
                    if seen.get(t, 1 << 60) <= g + 1:
                        continue
                    seen[t] = g + 1
                    if dfs(t, g + 1, limit, seen):
                        return True
        return False

    limit = h0
    while not dfs(start, 0, limit, {start: 0}):
        limit += 1
    return limit
